export const careersIndexHtml: string = "<header class=\"mc-careers-head\">\n    <p class=\"mc-eyebrow\">Careers \u00b7 4 open roles</p>\n    <h1 id=\"mc-careers-title\">Building the world-class market <span class=\"mc-accent\">research terminal</span></h1>\n    <p class=\"mc-lede\">MarketCatalyst, built by MarketCatalyst Analytics LLC, is an AI-powered stock market research terminal for traders and investors. We\u2019re an early-stage, founder-led team building research tools that explain the market with sources attached. We don\u2019t sell trade signals or give investment advice.</p>\n    <p class=\"mc-lede\">To apply, send your resume to <a href=\"mailto:hr@marketcatalyst.ai\">hr@marketcatalyst.ai</a>. Each role below has a link with the subject line already filled in.</p>\n  </header>\n\n  <div class=\"mc-jobs\">\n    <details class=\"mc-job\" id=\"research-analyst\" name=\"mc-jobs\">\n      <summary>\n        <span class=\"mc-job-head\">\n          <span class=\"mc-job-title\">Research Analyst \u2014 Equities and Markets</span>\n          <span class=\"mc-job-tags\"><span class=\"mc-tag\">Remote (Texas)</span><span class=\"mc-tag\">Full-time</span><span class=\"mc-tag\">$80k\u2013$120k</span></span>\n          <span class=\"mc-job-hook\">Fact-check and improve the AI-written market recaps, earnings reads and Why It Moved explanations, and write the research a machine can\u2019t.</span>\n        </span>\n        <span class=\"mc-chevron\" aria-hidden=\"true\"></span>\n      </summary>\n      <div class=\"mc-job-body\">\n        <p class=\"mc-role-link\"><a href=\"/careers/research-analyst\">Research Analyst \u2014 Equities and Markets: view the full role page \u2192</a></p>\n        <p>This is a remote role open to candidates who live in Texas. You can work from anywhere in the state.</p>\n        <h3>About the company</h3>\n        <p>MarketCatalyst (https://marketcatalyst.ai) is an AI-powered stock market research terminal for traders and investors: 16 workspaces covering movers, earnings, analyst actions, macro, SEC EDGAR insider and 13F ownership, ETFs, IPOs, screeners and AI recaps, plus a per-ticker Stock Intelligence view. Its content is generated by automated AI pipelines over sourced market data. It is a research and information platform that does not offer trade signals or investment advice. We're early-stage and founder-led, with a free tier and Pro ($29) and Elite ($79) plans.</p>\n        <h3>What you'll do</h3>\n        <ul>\n          <li>Review and fact-check AI-generated daily and weekly recaps, earnings reads and Why It Moved attributions against filings, transcripts and price data before and after they go live.</li>\n          <li>Cover the core research areas: earnings (EPS and revenue versus consensus, guidance, the reaction), analyst rating changes and price targets, insider Form 4 activity and 13F holdings, and macro releases and volatility.</li>\n          <li>Write and maintain evidence-first explainers and guides, such as how to read a 13F, what an earnings surprise means, and how to tell routine insider grants from open-market buys.</li>\n          <li>Build review checklists and error categories (wrong figure, wrong cause, stale data, advice-like wording) and feed them back to the data and AI teams so recurring errors get fixed at the source.</li>\n          <li>Keep all content on the research and education side of the line: no recommendations, price calls or language that reads like a trade signal.</li>\n          <li>Suggest new research views and data studies based on what traders and investors actually ask about.</li>\n        </ul>\n        <h3>What you bring</h3>\n        <ul>\n          <li>6+ years in equity research, financial journalism, investment research or a similar role where your accuracy was checked.</li>\n          <li>Fluency with 10-K/10-Q filings, earnings releases and call transcripts, consensus estimates and analyst actions.</li>\n          <li>Working knowledge of SEC EDGAR filings, especially Form 4 and 13F, and what they can and can't tell you.</li>\n          <li>Clear, plain English writing for a non-professional audience, with no hype.</li>\n          <li>The habit of checking every number against a primary source.</li>\n          <li>Comfort working with AI-generated drafts: spotting confident-sounding errors, missing context and wrong causation.</li>\n          <li>Understanding of the difference between financial education and investment advice.</li>\n        </ul>\n        <h3>Nice to have</h3>\n        <ul>\n          <li>CFA charter, CFA Level I/II, or similar coursework.</li>\n          <li>Basic SQL or Python, or advanced spreadsheet skills, to pull and check data yourself.</li>\n          <li>Experience with macro data (CPI, payrolls, Fed decisions) and the VIX.</li>\n          <li>Experience writing for SEO or editing at a publication with a style guide.</li>\n        </ul>\n        <h3>What we offer</h3>\n        <ul>\n          <li>Compensation: $80,000\u2013$120,000 per year</li>\n          <li>Equity may be offered to the right candidate.</li>\n          <li>Paid time off and flexible hours.</li>\n          <li>Direct influence on the editorial standards of a product used by traders and investors.</li>\n        </ul>\n        <h3>How to apply</h3>\n        <p>Send your resume to <a href=\"mailto:hr@marketcatalyst.ai?subject=Application:%20Research%20Analyst\">hr@marketcatalyst.ai</a> with the subject line \"Application: Research Analyst\". Include one short sample of financial writing. Optionally, add a few notes on a recent MarketCatalyst recap: what's right, what's wrong and what's missing.</p>\n        <h3>Equal opportunity</h3>\n        <p>MarketCatalyst Analytics LLC is an equal opportunity employer. We consider all qualified applicants without regard to race, color, religion, sex, sexual orientation, gender identity or expression, national origin, age, disability, veteran status, genetic information or any other status protected by applicable law. If you need an accommodation during the application process, email <a href=\"mailto:hr@marketcatalyst.ai?subject=Accommodation%20request\">hr@marketcatalyst.ai</a>.</p>\n        <p class=\"mc-apply\"><a class=\"mc-btn\" href=\"mailto:hr@marketcatalyst.ai?subject=Application:%20Research%20Analyst\">Apply: email hr@marketcatalyst.ai</a> <a class=\"mc-btn mc-btn-ghost\" href=\"/careers/research-analyst\">View full role</a></p>\n      </div>\n    </details>\n    <details class=\"mc-job\" id=\"data-analyst\" name=\"mc-jobs\">\n      <summary>\n        <span class=\"mc-job-head\">\n          <span class=\"mc-job-title\">Data Analyst \u2014 Market Data and Analytics</span>\n          <span class=\"mc-job-tags\"><span class=\"mc-tag\">Remote (Texas)</span><span class=\"mc-tag\">Full-time</span><span class=\"mc-tag\">$80k\u2013$120k</span></span>\n          <span class=\"mc-job-hook\">Keep the market, fundamentals and SEC EDGAR data trustworthy, measure product and SEO traffic, and publish original data studies.</span>\n        </span>\n        <span class=\"mc-chevron\" aria-hidden=\"true\"></span>\n      </summary>\n      <div class=\"mc-job-body\">\n        <p class=\"mc-role-link\"><a href=\"/careers/data-analyst\">Data Analyst \u2014 Market Data and Analytics: view the full role page \u2192</a></p>\n        <p>This is a remote role open to candidates who live in Texas. You can work from anywhere in the state.</p>\n        <h3>About the company</h3>\n        <p>MarketCatalyst (https://marketcatalyst.ai) is an AI-powered stock market research terminal for traders and investors: 16 workspaces covering movers, earnings, analyst actions, macro, SEC EDGAR insider and 13F ownership, ETFs, IPOs, screeners and AI recaps, plus a per-ticker Stock Intelligence view. Its content is generated by automated AI pipelines over sourced market data. It is a research and information platform that does not offer trade signals or investment advice. We're early-stage and founder-led, with a free tier and Pro ($29) and Elite ($79) plans.</p>\n        <h3>What you'll do</h3>\n        <ul>\n          <li>Monitor and improve the pipelines that ingest market feeds, fundamentals and SEC EDGAR filings (Form 4, 13F), working with engineering on fixes.</li>\n          <li>Build data-quality checks for missing tickers, stale prices, unit and currency mismatches, duplicate filings, split adjustments and identifiers that don't reconcile across vendors.</li>\n          <li>Write SQL and Python to answer product questions: which workspaces people use, where free users upgrade, and which recaps and pages bring readers back.</li>\n          <li>Own dashboards for data health, product usage and SEO and traffic (Google Search Console, analytics, indexing and crawl coverage).</li>\n          <li>Produce original, reproducible data studies for the blog and press, such as insider buying by sector, earnings reaction patterns or analyst rating clusters, with methods published alongside.</li>\n          <li>Document data definitions so research, AI and engineering use the same numbers.</li>\n        </ul>\n        <h3>What you bring</h3>\n        <ul>\n          <li>6+ years as a data analyst, analytics engineer or similar, ideally working with financial or market data.</li>\n          <li>Strong SQL, including window functions and joins across messy sources, and practical Python (pandas or polars).</li>\n          <li>Experience building and maintaining dashboards in a BI tool (e.g. Metabase, Looker Studio, Tableau, or similar).</li>\n          <li>Understanding of market-data basics: OHLCV, corporate actions, tickers versus identifiers, trading calendars and delayed versus real-time data.</li>\n          <li>A track record of finding and fixing data-quality problems rather than working around them.</li>\n          <li>Clear written communication: you can explain a chart and its caveats in a paragraph.</li>\n        </ul>\n        <h3>Nice to have</h3>\n        <ul>\n          <li>Hands-on experience with SEC EDGAR data (XBRL, Form 4 XML, 13F information tables).</li>\n          <li>Experience with Google Search Console, GA4 or other web analytics, and basic technical SEO.</li>\n          <li>Familiarity with orchestration and testing tools (e.g. Airflow, Dagster, dbt tests, Great Expectations).</li>\n          <li>Experience publishing data journalism or research others have cited.</li>\n        </ul>\n        <h3>What we offer</h3>\n        <ul>\n          <li>Compensation: $80,000\u2013$120,000 per year</li>\n          <li>Equity may be offered to the right candidate.</li>\n          <li>Paid time off and flexible hours.</li>\n          <li>Ownership of the data layer behind every screen and AI read in the product.</li>\n        </ul>\n        <h3>How to apply</h3>\n        <p>Send your resume to <a href=\"mailto:hr@marketcatalyst.ai?subject=Application:%20Data%20Analyst\">hr@marketcatalyst.ai</a> with the subject line \"Application: Data Analyst\". Include a link to, or a short description of, a data-quality problem you found and fixed, or an analysis you're proud of.</p>\n        <h3>Equal opportunity</h3>\n        <p>MarketCatalyst Analytics LLC is an equal opportunity employer. We consider all qualified applicants without regard to race, color, religion, sex, sexual orientation, gender identity or expression, national origin, age, disability, veteran status, genetic information or any other status protected by applicable law. If you need an accommodation during the application process, email <a href=\"mailto:hr@marketcatalyst.ai?subject=Accommodation%20request\">hr@marketcatalyst.ai</a>.</p>\n        <p class=\"mc-apply\"><a class=\"mc-btn\" href=\"mailto:hr@marketcatalyst.ai?subject=Application:%20Data%20Analyst\">Apply: email hr@marketcatalyst.ai</a> <a class=\"mc-btn mc-btn-ghost\" href=\"/careers/data-analyst\">View full role</a></p>\n      </div>\n    </details>\n    <details class=\"mc-job\" id=\"ai-ml-engineer\" name=\"mc-jobs\">\n      <summary>\n        <span class=\"mc-job-head\">\n          <span class=\"mc-job-title\">AI/ML Engineer \u2014 LLM Pipelines and Research AI</span>\n          <span class=\"mc-job-tags\"><span class=\"mc-tag\">Remote (Texas)</span><span class=\"mc-tag\">Full-time</span><span class=\"mc-tag\">$80k\u2013$120k</span></span>\n          <span class=\"mc-job-hook\">Own the LLM pipelines, attribution models, RAG grounding and evals behind every AI read in the product.</span>\n        </span>\n        <span class=\"mc-chevron\" aria-hidden=\"true\"></span>\n      </summary>\n      <div class=\"mc-job-body\">\n        <p class=\"mc-role-link\"><a href=\"/careers/ai-ml-engineer\">AI/ML Engineer \u2014 LLM Pipelines and Research AI: view the full role page \u2192</a></p>\n        <p>This is a remote role open to candidates who live in Texas. You can work from anywhere in the state.</p>\n        <h3>About the company</h3>\n        <p>MarketCatalyst (https://marketcatalyst.ai) is an AI-powered stock market research terminal for traders and investors: 16 workspaces covering movers, earnings, analyst actions, macro, SEC EDGAR insider and 13F ownership, ETFs, IPOs, screeners and AI recaps, plus a per-ticker Stock Intelligence view. Its content is generated by automated AI pipelines over sourced market data. It is a research and information platform that does not offer trade signals or investment advice. We're early-stage and founder-led, with a free tier and Pro ($29) and Elite ($79) plans.</p>\n        <h3>What you'll do</h3>\n        <ul>\n          <li>Build and run the LLM pipelines that generate the daily and weekly recaps, \"What Matters Now\" briefs and per-ticker reads from our normalized market data.</li>\n          <li>Improve Why It Moved attribution (linking price moves to news, filings, earnings and analyst actions) and the Why It Could Move catalyst scoring models.</li>\n          <li>Build retrieval and grounding (RAG) for the AI research chat, Thesis Lab and Thesis Monitor so answers cite the underlying data and filings and decline when the evidence isn't there.</li>\n          <li>Create evaluation sets and automated checks for factual accuracy, number consistency, hallucinated causes and advice-like language. Run them on every prompt or model change.</li>\n          <li>Manage cost, latency and reliability: model choice, caching, batching, fallbacks and monitoring for scheduled and interactive workloads.</li>\n          <li>Integrate AI features into the production Next.js app and APIs alongside the rest of the engineering work.</li>\n        </ul>\n        <h3>What you bring</h3>\n        <ul>\n          <li>6+ years in software or ML engineering, including at least one LLM-powered feature shipped to production.</li>\n          <li>Strong Python. Comfortable reading and writing TypeScript in a Next.js codebase.</li>\n          <li>Hands-on experience with RAG: chunking, embeddings, vector or hybrid search, reranking and citation of sources.</li>\n          <li>Experience designing LLM evaluations (golden sets, LLM-as-judge with spot checks, regression tests), not just eyeballing outputs.</li>\n          <li>Solid fundamentals in classical ML and statistics for attribution and scoring work (feature engineering, validation, avoiding leakage and look-ahead bias with time-series data).</li>\n          <li>Production habits: logging, monitoring, cost tracking and safe rollouts.</li>\n        </ul>\n        <h3>Nice to have</h3>\n        <ul>\n          <li>Experience with financial or market data, news-event attribution or event studies.</li>\n          <li>Experience with structured outputs, function calling or agent frameworks, and their failure modes.</li>\n          <li>Experience with Postgres, including pgvector or another vector store.</li>\n          <li>Interest in markets and in building AI that explains rather than predicts.</li>\n        </ul>\n        <h3>What we offer</h3>\n        <ul>\n          <li>Compensation: $80,000\u2013$120,000 per year</li>\n          <li>Equity may be offered to the right candidate.</li>\n          <li>Paid time off and flexible hours.</li>\n          <li>Ownership of the AI system at the center of the product, early enough to set its architecture and standards.</li>\n        </ul>\n        <h3>How to apply</h3>\n        <p>Send your resume to <a href=\"mailto:hr@marketcatalyst.ai?subject=Application:%20AI%2FML%20Engineer\">hr@marketcatalyst.ai</a> with the subject line \"Application: AI/ML Engineer\". Include a short note (or link) on an LLM system you shipped: how you measured whether it was right and what you changed as a result.</p>\n        <h3>Equal opportunity</h3>\n        <p>MarketCatalyst Analytics LLC is an equal opportunity employer. We consider all qualified applicants without regard to race, color, religion, sex, sexual orientation, gender identity or expression, national origin, age, disability, veteran status, genetic information or any other status protected by applicable law. If you need an accommodation during the application process, email <a href=\"mailto:hr@marketcatalyst.ai?subject=Accommodation%20request\">hr@marketcatalyst.ai</a>.</p>\n        <p class=\"mc-apply\"><a class=\"mc-btn\" href=\"mailto:hr@marketcatalyst.ai?subject=Application:%20AI%2FML%20Engineer\">Apply: email hr@marketcatalyst.ai</a> <a class=\"mc-btn mc-btn-ghost\" href=\"/careers/ai-ml-engineer\">View full role</a></p>\n      </div>\n    </details>\n    <details class=\"mc-job\" id=\"full-stack-engineer\" name=\"mc-jobs\">\n      <summary>\n        <span class=\"mc-job-head\">\n          <span class=\"mc-job-title\">Full-Stack Engineer (Node.js)</span>\n          <span class=\"mc-job-tags\"><span class=\"mc-tag\">Remote (Texas)</span><span class=\"mc-tag\">Full-time</span><span class=\"mc-tag\">$80k\u2013$120k</span></span>\n          <span class=\"mc-job-hook\">Own product features end to end across the Node.js/TypeScript backend and the Next.js front end, from APIs and billing to charts, performance and SEO.</span>\n        </span>\n        <span class=\"mc-chevron\" aria-hidden=\"true\"></span>\n      </summary>\n      <div class=\"mc-job-body\">\n        <p class=\"mc-role-link\"><a href=\"/careers/full-stack-engineer\">Full-Stack Engineer (Node.js): view the full role page \u2192</a></p>\n        <p>This is a remote role open to candidates who live in Texas. You can work from anywhere in the state.</p>\n        <h3>About the company</h3>\n        <p>MarketCatalyst (https://marketcatalyst.ai) is an AI-powered stock market research terminal for traders and investors: 16 workspaces covering movers, earnings, analyst actions, macro, SEC EDGAR insider and 13F ownership, ETFs, IPOs, screeners and AI recaps, plus a per-ticker Stock Intelligence view. Its content is generated by automated AI pipelines over sourced market data. It is a research and information platform that does not offer trade signals or investment advice. We're early-stage and founder-led, with a free tier and Pro ($29) and Elite ($79) plans.</p>\n        <h3>What you'll do</h3>\n        <ul>\n          <li>Build and own product features end to end across the Node.js/TypeScript backend and the Next.js/React front end, including the dashboard, the Stock Intelligence views and charts.</li>\n          <li>Design and maintain the APIs and data services that feed the 16 workspaces, working with the data team on schemas, caching and freshness.</li>\n          <li>Own authentication, accounts and billing for the Free, Pro and Elite plans, including plan-based access and delayed versus real-time data.</li>\n          <li>Integrate the AI pipelines' output (recaps, What Matters Now briefs, Why It Moved, research chat) into the app, with loading states, sources and graceful failures.</li>\n          <li>Keep the app fast: performance budgets, Core Web Vitals, bundle size, and query and API latency.</li>\n          <li>Own SEO-critical rendering: SSR/SSG and incremental regeneration, structured data, canonical tags, sitemaps and indexability for a large and growing set of auto-generated pages.</li>\n          <li>Ship with tests, CI and monitoring, and review code with the rest of the team.</li>\n        </ul>\n        <h3>What you bring</h3>\n        <ul>\n          <li>6+ years of full-stack engineering experience, shipping and maintaining production web applications.</li>\n          <li>Strong Node.js and TypeScript on the backend.</li>\n          <li>Strong React and Next.js on the front end, including server rendering and data fetching patterns.</li>\n          <li>Solid PostgreSQL (or a similar relational database): schema design, indexing and query tuning.</li>\n          <li>Experience designing and consuming REST and/or GraphQL APIs.</li>\n          <li>Hands-on experience with cloud deployments and CI/CD pipelines.</li>\n          <li>Good judgment about trade-offs between speed, reliability and simplicity on a small team.</li>\n        </ul>\n        <h3>Nice to have</h3>\n        <ul>\n          <li>Real-time market data or WebSocket streaming experience.</li>\n          <li>Experience with charting libraries (e.g. TradingView Lightweight Charts, D3, ECharts, Recharts).</li>\n          <li>Stripe billing and subscription experience.</li>\n          <li>SEO for large content sites: crawl budget, structured data, Core Web Vitals at scale.</li>\n        </ul>\n        <h3>What we offer</h3>\n        <ul>\n          <li>Compensation: $80,000\u2013$120,000 per year</li>\n          <li>Equity may be offered to the right candidate.</li>\n          <li>Paid time off and flexible hours.</li>\n          <li>Ownership of the product's architecture and user experience at an early stage.</li>\n        </ul>\n        <h3>How to apply</h3>\n        <p>Send your resume to <a href=\"mailto:hr@marketcatalyst.ai?subject=Application:%20Full-Stack%20Engineer\">hr@marketcatalyst.ai</a> with the subject line \"Application: Full-Stack Engineer\". Include a link to, or a short note on, a product feature you built end to end: what you owned, and how you measured whether it worked.</p>\n        <h3>Equal opportunity</h3>\n        <p>MarketCatalyst Analytics LLC is an equal opportunity employer. We consider all qualified applicants without regard to race, color, religion, sex, sexual orientation, gender identity or expression, national origin, age, disability, veteran status, genetic information or any other status protected by applicable law. If you need an accommodation during the application process, email <a href=\"mailto:hr@marketcatalyst.ai?subject=Accommodation%20request\">hr@marketcatalyst.ai</a>.</p>\n        <p class=\"mc-apply\"><a class=\"mc-btn\" href=\"mailto:hr@marketcatalyst.ai?subject=Application:%20Full-Stack%20Engineer\">Apply: email hr@marketcatalyst.ai</a> <a class=\"mc-btn mc-btn-ghost\" href=\"/careers/full-stack-engineer\">View full role</a></p>\n      </div>\n    </details>\n  </div>";
